// Convert form fields into the same shape the webhook delivers ({ body: {...} })
return $input.all().map(item => {
  const f = item.json;
  return { json: { body: {
    bench_id: f['Bench ID'],
    step_id: String(f['Step'] || '').slice(0, 3),
    status: f['Status'],
    technician: f['Technician'],
    comment: f['Comment'] || '',
    source: 'form',
  } } };
});

const STEPS = {
  S01: 'Mechanical installation & wiring check',
  S02: 'Power-up & safety circuit (E-Stop) test',
  S03: 'Network / CAN communication check',
  S04: 'Sensor & actuator calibration',
  S05: 'Software flashing & HIL configuration',
  S06: 'Reference test run',
  S07: 'Documentation & release / handover',
};
const ALLOWED = ['PASS', 'FAIL', 'BLOCKED', 'IN_PROGRESS'];

return $input.all().map(item => {
  const b = item.json.body || {};
  const errors = [];
  if (!b.bench_id) errors.push('bench_id is required');
  if (!STEPS[b.step_id]) errors.push(`step_id must be one of ${Object.keys(STEPS).join(', ')}`);
  const status = String(b.status || '').toUpperCase();
  if (!ALLOWED.includes(status)) errors.push(`status must be one of ${ALLOWED.join(', ')}`);
  if (!b.technician) errors.push('technician is required');

  return {
    json: {
      valid: errors.length === 0,
      errors,
      record: {
        bench_id: String(b.bench_id || '').trim().toUpperCase(),
        step_id: b.step_id,
        step_name: STEPS[b.step_id] || null,
        status,
        technician: b.technician || null,
        comment: b.comment || '',
        measurements: b.measurements || {},
        timestamp: new Date().toISOString(),
        total_steps: Object.keys(STEPS).length,
      },
    },
  };
});

// Simple persistence for the demo: workflow static data (only saved for
// production executions, i.e. when the workflow is active).
// In a real setup replace this with SharePoint / Microsoft Lists / Postgres.
const db = $getWorkflowStaticData('global');
db.benches = db.benches || {};
db.log = db.log || [];

return $input.all().map(item => {
  const r = item.json.record;
  const bench = db.benches[r.bench_id] = db.benches[r.bench_id] || { steps: {}, created_at: r.timestamp };
  bench.steps[r.step_id] = {
    status: r.status, step_name: r.step_name, technician: r.technician,
    comment: r.comment, timestamp: r.timestamp,
  };
  bench.updated_at = r.timestamp;

  db.log.push(r);
  if (db.log.length > 500) db.log.shift();

  const passed = Object.values(bench.steps).filter(s => s.status === 'PASS').length;
  const progress_pct = Math.round((passed / r.total_steps) * 100);
  return { json: { ...r, progress_pct, release_ready: passed === r.total_steps } };
});

const STEPS = {
  S01: 'Mechanical installation & wiring check',
  S02: 'Power-up & safety circuit (E-Stop) test',
  S03: 'Network / CAN communication check',
  S04: 'Sensor & actuator calibration',
  S05: 'Software flashing & HIL configuration',
  S06: 'Reference test run',
  S07: 'Documentation & release / handover',
};
// Process model: which step depends on which (S04 and S05 can run in parallel)
const DEPS = { S01: [], S02: ['S01'], S03: ['S02'], S04: ['S03'], S05: ['S03'], S06: ['S04', 'S05'], S07: ['S06'] };
// Who is responsible for each step (role, not person -> no notification flood)
const OWNER = { S01: 'Mechanik', S02: 'Elektrik', S03: 'Elektrik', S04: 'Messtechnik', S05: 'Software', S06: 'Prüfingenieur', S07: 'Projektleitung' };
const done = (b, s) => b.steps[s]?.status === 'PASS';
const readyToStart = b => Object.keys(STEPS).filter(s => !b.steps[s] && DEPS[s].every(d => done(b, d)));
const downstream = s => { const out = new Set(); const walk = x => Object.keys(DEPS).filter(k => DEPS[k].includes(x)).forEach(k => { if (!out.has(k)) { out.add(k); walk(k); } }); walk(s); return [...out].sort(); };

// Decide WHO gets notified and HOW URGENT, instead of notifying everyone about everything.
//  P1 = immediate alert (step FAILED or BLOCKED -> blocks downstream work)
//  P2 = one targeted handover message to the role whose step is now unblocked
//  P3 = no push at all, only in the daily digest (IN_PROGRESS, PASS without handover)
const db = $getWorkflowStaticData('global');
db.notifications = db.notifications || [];
const out = [];

for (const item of $input.all()) {
  const r = item.json;
  const bench = db.benches[r.bench_id];
  const notes = [];

  if (r.status === 'FAIL' || r.status === 'BLOCKED') {
    const blocked = downstream(r.step_id);
    notes.push({
      priority: 'P1', to: [OWNER[r.step_id], 'Projektleitung'],
      text: `${r.bench_id}: ${r.step_id} ${r.step_name} is ${r.status}` + (r.comment ? ` (${r.comment})` : '') +
            `. Blocks ${blocked.length} following step(s): ${blocked.join(', ') || 'none'}.`,
    });
  } else if (r.status === 'PASS') {
    const unblocked = readyToStart(bench).filter(s => DEPS[s].includes(r.step_id));
    for (const s of unblocked) {
      notes.push({ priority: 'P2', to: [OWNER[s]], text: `${r.bench_id}: ${s} ${STEPS[s]} can start now (${r.step_id} passed).` });
    }
  }

  for (const n of notes) {
    const rec = { ...n, bench_id: r.bench_id, step_id: r.step_id, at: r.timestamp };
    db.notifications.push(rec);
    if (db.notifications.length > 200) db.notifications.shift();
    out.push({ json: rec });
  }
}
return out;   // P3 events produce no item -> no notification at all

